CREATE OR REPLACE FUNCTION public.department_manager(a text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(public.general_approver() OR (public.staff_role() LIKE '%Manager' AND public.staff_department()=public.area_department(a)),false) $$;
CREATE OR REPLACE FUNCTION public.operation_access(op text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(public.general_approver() OR public.staff_role()='Admin' OR (public.staff_role() LIKE '%Manager' AND (EXISTS(SELECT 1 FROM public.operation_assignments WHERE operation_id=op AND public.area_department(area)=public.staff_department()) OR EXISTS(SELECT 1 FROM public.erp_work WHERE operation_id=op AND public.area_department(area)=public.staff_department()))) OR EXISTS(SELECT 1 FROM public.operation_assignments WHERE operation_id=op AND user_id=auth.uid() AND area=public.staff_area()),false) $$;